-- AUTOMATISCH ERZEUGT aus daten/ (npm run seed) – nicht von Hand bearbeiten.
-- Teil von supabase/seed.sql: Thema 22 „Radikalisierung und Extremismus“ – Instrumente, Maßnahmen, Prüfeinheiten, Abdeckung.
-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 22;
delete from public.abdeckung where thema_id = 22;
delete from public.pruef_einheiten where thema_id = 22;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8984, 22, 'Ausstiegs-, Distanzierungs- und Deradikalisierungsberatung ausbauen und absichern (Land)', 'Setzt direkt an Bindungen ans Milieu an; Review zeigt Erfolge v. a. bei Ausstieg mit Bildung, Arbeit, sozialer Einbindung. Dagegen: wenige belastbare Wirkungsevaluationen, Deradikalisierung im engeren Sinn wirkt im Schnitt schwächer.', 'gemischt', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/1027', 'land', null, true, 'blind'),
  (8985, 22, 'Präventions- und Demokratieprojekte gegen Extremismus fördern und gesetzlich absichern (Land)', 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'gemischt', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'land', null, true, 'blind'),
  (8986, 22, 'Strategien und Konzepte gegen Extremismus und Rassismus erarbeiten oder bestehende Programme überprüfen (Land)', 'Kann Prävention bündeln und Lücken schließen; ohne zusätzliche Angebote bleibt die Wirkung aber mittelbar und hängt von der späteren Umsetzung ab. Zur Wirkung solcher Strategien gibt es kaum Studien.', 'offen', null, 'land', null, true, 'blind'),
  (8987, 22, 'Allgemeine Jugend- und Straßensozialarbeit ausbauen (Land)', 'Bietet Jugendlichen Anlaufstellen und Alternativen zu Milieus, ist aber nicht gezielt auf Radikalisierung ausgerichtet; Fachkräfte sind knapp. Spezifische Wirkung auf Extremismus kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8988, 22, 'Staatliche Förderung und Kooperation für extremistische Organisationen ausschließen (Demokratieklausel) (Land)', 'Verhindert, dass öffentliche Mittel extremistische Strukturen stützen; solche Förderungen sind aber selten. Unbestimmte Klauseln wurden gerichtlich beanstandet (VG Dresden 2012), rechtssichere Fassung ist möglich. Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8989, 22, 'Förderpraxis auf Ausgewogenheit ausrichten, Förderung von Meldestellen und Kampagnenprojekten beenden (Land)', 'Kann bei Teilen der Bevölkerung das Gefühl von Bevormundung und Ungleichbehandlung mindern. Dagegen: Streichungen schwächen Dokumentation und Präventionsarbeit; Wirkung auf Gesprächskultur nicht untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8990, 22, 'Politische und historische Bildung in Kita, Schule, Lehrkräftebildung und Landeszentrale ausbauen (Land)', 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'gemischt', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'land', null, true, 'blind'),
  (8991, 22, 'Antisemitismus- und Rassismusprävention in Schulen und Hochschulen verankern (Land)', 'Setzt an Vorurteilen und Überlegenheitsdenken an; Begegnungsformate wirken eher. Dagegen: Metaanalyse findet bei vielen Vorurteilsprogrammen nur kurzfristige, kleine Effekte und Hinweise auf Publikationsbias.', 'gemischt', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'land', null, true, 'blind'),
  (8992, 22, 'Soziales Lernen, Respekt und Toleranz als schulischen Auftrag stärken (Land)', 'Programme zum sozialen Lernen verbessern Sozialverhalten und Einstellungen nachweislich. Die Maßnahmen bleiben aber meist unbestimmt, und ein Effekt auf politische Toleranz ist kaum untersucht.', 'belegt', 'https://ojp.gov/ncjrs/virtual-library/abstracts/impact-enhancing-students-social-and-emotional-learning-meta', 'land', null, true, 'blind'),
  (8993, 22, 'Neutralitäts- und Kontroversitätsgebot für den Unterricht verschärfen (Land)', 'Ein offenes Klassenklima kann Vertrauen und Toleranz fördern; das Kontroversitätsgebot gilt aber bereits weitgehend. Strengere Neutralität kann Lehrkräfte auch von der Auseinandersetzung mit Extremismus abhalten.', 'offen', null, 'land', null, true, 'blind'),
  (8994, 22, 'Schülermitbestimmung und Klassenrat stärken (Land)', 'Mitwirkung in Schulgremien hängt in Panelstudien mit politischer Wirksamkeit und Beteiligung zusammen und übt Streitkultur. Dagegen: Effekt auf Eskalation politischer Gespräche nicht direkt untersucht.', 'gemischt', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'land', null, true, 'blind'),
  (8995, 22, 'Fortbildung von Beschäftigten in Schule, Polizei und Verwaltung zu Demokratie, Diskriminierung und Extremismus (Land)', 'Trainings verbessern Wissen dauerhaft, Einstellungseffekte schwinden aber ohne Einbettung. Erreicht Multiplikatoren, wirkt auf die Bevölkerung nur mittelbar.', 'gemischt', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'land', null, true, 'blind'),
  (8996, 22, 'Verfassungstreue im öffentlichen Dienst prüfen und Verfassungsfeinde schneller entfernen (Land)', 'Verhindert, dass Staatsbedienstete extremistische Ideologien weitertragen, und schützt Vertrauen in Institutionen. Ändert Einstellungen in der Bevölkerung kaum; Wirkung nicht untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8997, 22, 'Geloste Bürgerräte auf Landes- und Kommunalebene einrichten und fördern (Land)', 'Deliberation senkte im Feldexperiment affektive Polarisierung deutlich und gibt Mitsprache. Dagegen: erreicht direkt nur wenige; Effekte auf Vertrauen der übrigen Bevölkerung uneinheitlich.', 'gemischt', 'https://deliberation.stanford.edu/publications/journal-articles/deliberation-antidote-extreme-partisan-polarization-reflections', 'land', null, true, 'blind'),
  (8998, 22, 'Sonstige Beteiligungs- und Dialogformate zwischen Politik, Verwaltung und Bürgern ausbauen (Land)', 'Kann Kontrollverlust und Gefühl der Bevormundung mindern. Dagegen: Wirkung hängt davon ab, ob Ergebnisse berücksichtigt werden; ohne Folgen droht Enttäuschung. Kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (8999, 22, 'Direkte Demokratie im Land ausbauen (niedrigere Quoren, Volksbefragungen, Verbindlichkeit) (Land)', 'Verfügbare Volksrechte gehen in der Schweiz mit mehr Vertrauen einher, häufige Nutzung teils mit weniger. Quoren stehen meist in der Landesverfassung, Änderung braucht Zweidrittelmehrheit.', 'gemischt', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'land', null, true, 'blind'),
  (9000, 22, 'Dialog- und Begegnungsformate fördern (interreligiös, interkulturell, moderierte Debattenräume) (Land)', 'Kontakt verringert Vorurteile laut Metaanalysen und Feldexperimenten. Dagegen: neuere vorregistrierte Studien finden kleinere Effekte, die oft auf die getroffenen Personen begrenzt bleiben.', 'gemischt', 'https://forrt.org/open-social-psychology/chapter12.html', 'land', null, true, 'blind'),
  (9001, 22, 'Wissenschafts- und Meinungsfreiheit sowie offene Debattenkultur an Hochschulen absichern (Land)', 'Kann das Gefühl verringern, Positionen würden sanktioniert, und Streit an Hochschulen versachlichen. Dagegen: bestehender Grundrechtsschutz, unklare Reichweite; Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9002, 22, 'Staatliche Zurückhaltung gegenüber nicht strafbaren Meinungsäußerungen und Protesten (Land)', 'Kann wahrgenommene Bevormundung und Ungleichbehandlung mindern. Dagegen: Rechtslage schützt nicht strafbare Äußerungen bereits weitgehend; Wirkung nicht untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9003, 22, 'Lokaljournalismus und Bürgermedien fördern (Land)', 'Schließungen von Lokalzeitungen erhöhen nachweislich politische Polarisierung, auch in Deutschland. Dagegen: ob Förderung Schließungen verhindert, ist offen; Umfang der Förderung entscheidet.', 'belegt', 'https://ideas.repec.org/a/cup/bjposi/v54y2024i4p1256-1275_12.html', 'land', null, true, 'blind'),
  (9004, 22, 'Löschpflichten und Moderation von Plattformen zurücknehmen (Land)', 'Studien zeigen, dass Sperren extremistischer Accounts deren Reichweite senkt; weniger Moderation erhöht eher den Kontakt mit solchen Inhalten. Plattformrecht ist durch den DSA europäisch geregelt.', 'gemischt', 'https://www.rutgers.edu/news/permanent-twitter-ban-extremist-influencers-can-detoxify-social-media', 'land', null, true, 'blind'),
  (9005, 22, 'Zusammenarbeit mit Moscheegemeinden und staatliche Aufsicht gegen islamistischen Einfluss (Land)', 'Kann Zugang zu Milieus und Verbreitung islamistischer Ideologie erschweren. Dagegen: Pflichten für Verbände berühren Religionsfreiheit; Review warnt vor Nebenwirkungen gruppenbezogener Ansätze.', 'offen', null, 'land', null, true, 'blind'),
  (9006, 22, 'Verpflichtende Werte- und Politikkurse für Zugewanderte (Land)', 'Vermittelt demokratische Grundwerte; Integrationskurse regelt aber der Bund, das Land kann kaum verpflichten. Wirkung auf Einstellungen kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9007, 22, 'Medien- und Nachrichtenkompetenz für alle Altersgruppen fördern (Bund)', 'Experimente zeigen, dass Medienkompetenz-Trainings die Unterscheidung von Falsch- und Qualitätsnachrichten verbessern. Effekte sind moderat und schwinden; Schulbildung liegt bei den Ländern.', 'belegt', 'https://collaborate.princeton.edu/en/publications/a-digital-media-literacy-intervention-increases-discernment-betwe/', 'bund', null, true, 'blind'),
  (9008, 22, 'Bestehende Plattformregeln (DSA) gegen rechtswidrige Inhalte konsequent durchsetzen (Bund)', 'Sperren extremistischer Akteure senkten deren Reichweite deutlich. Dagegen: Inhalte wandern teils auf andere Plattformen ab, wo Nutzer sich weiter radikalisieren können.', 'gemischt', 'https://www.rutgers.edu/news/permanent-twitter-ban-extremist-influencers-can-detoxify-social-media', 'bund', null, true, 'blind'),
  (9009, 22, 'Zusätzliche EU-Pflichten für Plattformen gegen Desinformation (Faktencheck, KI-Kennzeichnung, Haftung) (Bund)', 'Faktenchecks korrigieren Fehlinformationen moderat, bei politisch Überzeugten schwächer; Desinformation ist nicht gleich extremistischer Inhalt. Hängt von EU-Entscheidungen ab.', 'gemischt', 'https://cris.haifa.ac.il/en/publications/fact-checking-a-meta-analysis-of-what-works-and-for-whom/', 'bund', null, true, 'blind'),
  (9010, 22, 'Geloste Bürgerräte auf Bundesebene etablieren und gesetzlich absichern (Bund)', 'Deliberation senkte im Feldexperiment affektive Polarisierung deutlich und kann Vertrauen stärken. Dagegen: erreicht direkt nur wenige; Wirkung auf die Gesamtbevölkerung uneinheitlich.', 'gemischt', 'https://deliberation.stanford.edu/publications/journal-articles/deliberation-antidote-extreme-partisan-polarization-reflections', 'bund', null, true, 'blind'),
  (9011, 22, 'Volksbegehren und Volksentscheide auf Bundesebene einführen (Bund)', 'Verfügbare Volksrechte gehen mit mehr Institutionenvertrauen einher, häufige Nutzung teils mit weniger. Erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'gemischt', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'bund', null, true, 'blind'),
  (9012, 22, 'Integritätsregeln für Politik: Karenzzeiten, Spendenbegrenzung, legislative Fußspur, Kontrolle (Bund)', 'Setzt am geringen Vertrauen in Institutionen an, indem Interessenkonflikte begrenzt werden. Dagegen: Wirkung auf Vertrauen und radikale Einstellungen kaum untersucht, eher mittelbar.', 'offen', null, 'bund', null, true, 'blind'),
  (9013, 22, 'Unabhängigkeit von Staatsanwaltschaft und Richterwahl von der Politik stärken (Bund)', 'Kann Vertrauen in eine unparteiische Justiz stärken. Dagegen: Zusammenhang mit radikalen Einstellungen nur mittelbar; teils Grundgesetz- und Länderfragen berührt.', 'offen', null, 'bund', null, true, 'blind'),
  (9014, 22, 'Amtszeitbegrenzung und Direktwahl des Bundespräsidenten (Bund)', 'Soll Bürgernähe und Vertrauen stärken; Wirkung auf Institutionenvertrauen nicht untersucht. Erfordert Grundgesetzänderungen.', 'offen', null, 'bund', null, true, 'blind'),
  (9015, 22, 'Aufsicht und Programmauftrag des öffentlich-rechtlichen Rundfunks auf Staatsferne und Vielfalt ausrichten (Bund)', 'Kann Misstrauen gegenüber Medien und Gefühl der Bevormundung verringern. Dagegen: Wirkung kaum untersucht; Rundfunkrecht ist Ländersache, der Bund kann es nicht regeln.', 'offen', null, 'bund', null, true, 'blind'),
  (9016, 22, 'Neutralität von Lehrkräften und freie Meinungsäußerung von Schülern sichern (Bund)', 'Offenes Klassenklima kann Vertrauen und Toleranz stützen; Neutralitäts- und Kontroversitätsgebot gelten bereits. Schulrecht ist Ländersache.', 'offen', null, 'bund', null, true, 'blind'),
  (9017, 22, 'Verbände mit Extremismusbezug von Förderung und staatlicher Kooperation ausschließen (Bund)', 'Verhindert, dass staatliche Mittel und Anerkennung extremistische Milieus stützen. Dagegen: rechtssichere, bestimmte Kriterien nötig; Wirkung auf Einstellungen nicht untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (9018, 22, 'Staatliche Förderung von Meldestellen und meinungsbildenden Akteuren beenden (Bund)', 'Kann bei Teilen der Bevölkerung das Gefühl der Bevormundung mindern. Dagegen: Wegfall von Dokumentation und Beratung; Wirkung auf Gesprächskultur nicht untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (9019, 22, 'Imamausbildung im Inland, Religionsunterricht ohne Auslandseinfluss, Transparenz religiöser Finanzierung (Bund)', 'Kann ausländische und islamistische Einflussnahme auf Gemeinden begrenzen. Dagegen: Pflichten berühren Religionsfreiheit und Länderzuständigkeit; Wirkung kaum untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (9020, 22, 'Bundesförderung politischer und historischer Bildung und Gedenkstätten (Bund)', 'Bildungsarbeit setzt an Ideologien an; der Bund fördert bereits. Dagegen: Wirkung von Gedenkstättenbesuchen und Bildungsangeboten auf Einstellungen schwer belegbar, Erwartungen laut Forschung oft überzogen.', 'gemischt', 'https://www.news4teachers.de/2023/01/holocaust-gedenktag-debatte-um-verpflichtende-gedenkstaetten-besuche-von-schuelern-was-bringen-sie-wirklich/', 'bund', null, true, 'blind'),
  (9021, 22, 'Politische Bildung und Gedenkstättenbesuche verbindlich in Schulen verankern (Bund)', 'Kann historisches Bewusstsein stärken. Dagegen: Pflichtbesuche wirken laut Forschung nur mit guter Vor- und Nachbereitung, sonst teils Abwehr; Schule ist Ländersache, der Bund kann nur fördern.', 'gemischt', 'https://www.news4teachers.de/2023/01/holocaust-gedenktag-debatte-um-verpflichtende-gedenkstaetten-besuche-von-schuelern-was-bringen-sie-wirklich/', 'bund', null, true, 'blind'),
  (9022, 22, 'Verfassungsfeinde schneller aus dem öffentlichen Dienst entfernen (Bund)', 'Verhindert, dass Staatsbedienstete extremistische Ideologien weitertragen. Ändert Einstellungen in der Bevölkerung kaum; Wirkung nicht untersucht.', 'offen', null, 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 22 and id not in (8984, 8985, 8986, 8987, 8988, 8989, 8990, 8991, 8992, 8993, 8994, 8995, 8996, 8997, 8998, 8999, 9000, 9001, 9002, 9003, 9004, 9005, 9006, 9007, 9008, 9009, 9010, 9011, 9012, 9013, 9014, 9015, 9016, 9017, 9018, 9019, 9020, 9021, 9022);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9023, 22, 11, null, 'Digital Services Act mit Schwerpunkt auf Transparenz, Desinformation sowie Jugend- und Medienschutz umsetzen', '{2202}', 9008, 2, 3, null, 'Sperren extremistischer Akteure senkten deren Reichweite deutlich. Dagegen: Inhalte wandern teils auf andere Plattformen ab, wo Nutzer sich weiter radikalisieren können.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', 'https://www.rutgers.edu/news/permanent-twitter-ban-extremist-influencers-can-detoxify-social-media', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9024, 22, 11, null, 'Grundlagenforschung an Hochschulen zu gewaltbereitem und nicht gewaltsamem Islamismus ausbauen', '{2204}', null, 1, 3, null, 'Forschung zu Islamismus verbessert das Wissen für Prävention. Wirkt nur mittelbar über spätere Maßnahmen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9025, 22, 11, null, 'Vereine, die vom Verfassungsschutz beobachtet werden, von staatlichen Kooperationen und Geldern ausschließen; Geförderte bekennen sich zur Grundordnung', '{2204}', 9017, 1, 2, null, 'Verhindert, dass staatliche Mittel und Anerkennung extremistische Milieus stützen. Dagegen: rechtssichere, bestimmte Kriterien nötig; Wirkung auf Einstellungen nicht untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9026, 22, 11, null, 'Gedenkstättenbesuche für alle Schülerinnen und Schüler; Aufbau des Deutsch-Israelischen Jugendwerks vorantreiben', '{2204}', 9021, 1, 2, null, 'Kann historisches Bewusstsein stärken. Dagegen: Pflichtbesuche wirken laut Forschung nur mit guter Vor- und Nachbereitung, sonst teils Abwehr; Schule ist Ländersache, der Bund kann nur fördern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=46', 'https://www.news4teachers.de/2023/01/holocaust-gedenktag-debatte-um-verpflichtende-gedenkstaetten-besuche-von-schuelern-was-bringen-sie-wirklich/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9027, 22, 11, null, 'Feinde der freiheitlich-demokratischen Grundordnung schneller aus dem Öffentlichen Dienst entfernen', '{2204}', 9022, 1, 3, null, 'Verhindert, dass Staatsbedienstete extremistische Ideologien weitertragen. Ändert Einstellungen in der Bevölkerung kaum; Wirkung nicht untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9028, 22, 11, null, 'Pflicht zur Offenlegung der Finanzierung und Spender von Moscheevereinen und Islamverbänden', '{2204}', 9019, 1, 2, null, 'Kann ausländische und islamistische Einflussnahme auf Gemeinden begrenzen. Dagegen: Pflichten berühren Religionsfreiheit und Länderzuständigkeit; Wirkung kaum untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=59', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9029, 22, 11, null, 'Öffentlich-rechtlichen Rundfunk auf Neutralität, Meinungsvielfalt und Sparsamkeit verpflichten', '{2205}', 9015, 1, 1, null, 'Kann Misstrauen gegenüber Medien und Gefühl der Bevormundung verringern. Dagegen: Wirkung kaum untersucht; Rundfunkrecht ist Ländersache, der Bund kann es nicht regeln.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=57', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9030, 22, 11, null, 'Verpflichtendes Gesellschaftsjahr (perspektivisch), das Menschen unterschiedlicher Milieus, Religionen und Generationen zusammenbringt', '{2206}', null, 1, 1, null, 'Ein Dienstjahr bringt Milieus zusammen; Kontakt kann Vorurteile abbauen. Dagegen: nur perspektivisch, Pflichtdienst erfordert Grundgesetzänderung; Kontakteffekte oft klein.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=57', null, 'gemischt', '2026-10-10', false, true, 'blind'),
  (9031, 22, 11, 'BE', 'Aussteigerprogramme bedarfsgerecht fortführen.', '{2201}', 8984, 2, 3, null, 'Setzt direkt an Bindungen ans Milieu an; Review zeigt Erfolge v. a. bei Ausstieg mit Bildung, Arbeit, sozialer Einbindung. Dagegen: wenige belastbare Wirkungsevaluationen, Deradikalisierung im engeren Sinn wirkt im Schnitt schwächer.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/1027', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9032, 22, 11, 'BE', 'Organisationen, die gegen die demokratische Grundordnung stehen, keine staatlichen Fördergelder geben.', '{2201}', 8988, 1, 2, null, 'Verhindert, dass öffentliche Mittel extremistische Strukturen stützen; solche Förderungen sind aber selten. Unbestimmte Klauseln wurden gerichtlich beanstandet (VG Dresden 2012), rechtssichere Fassung ist möglich. Wirkung kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9033, 22, 11, 'BE', 'Jugendclubs als Orte der Begegnung und Demokratiebildung fördern, um Radikalisierung entgegenzuwirken.', '{2201}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=64', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9034, 22, 11, 'BE', 'Einen Verfassungstreue-Check im öffentlichen Dienst einführen.', '{2204}', 8996, 1, 3, null, 'Verhindert, dass Staatsbedienstete extremistische Ideologien weitertragen, und schützt Vertrauen in Institutionen. Ändert Einstellungen in der Bevölkerung kaum; Wirkung nicht untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9035, 22, 11, 'BE', 'Schulunterricht soll sich mit Extremismus sowie antisemitischen und rassistischen Ideologien auseinandersetzen.', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=63', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9036, 22, 11, 'BE', 'Projekte fördern, die demokratische Werte vermitteln und gegen Extremismus und Menschenfeindlichkeit eintreten.', '{2204}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=120', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9037, 22, 11, 'BE', 'Interreligiösen Dialog und Kulturprojekte fördern, die gegenseitiges Verständnis stärken.', '{2205,2206}', 9000, 2, 3, null, 'Kontakt verringert Vorurteile laut Metaanalysen und Feldexperimenten. Dagegen: neuere vorregistrierte Studien finden kleinere Effekte, die oft auf die getroffenen Personen begrenzt bleiben.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=117', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9038, 22, 11, 'BE', 'Eine Strategie entwickeln, die Prävention, Intervention und Repression an Schulen verbindet.', '{2204}', 8986, 1, 3, null, 'Kann Prävention bündeln und Lücken schließen; ohne zusätzliche Angebote bleibt die Wirkung aber mittelbar und hängt von der späteren Umsetzung ab. Zur Wirkung solcher Strategien gibt es kaum Studien.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=60', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9039, 22, 11, 'MV', 'Präventionsmaßnahmen und politische Bildung sollen Interventionen gegen Extremismus flankieren.', '{2201}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=38', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9040, 22, 11, 'MV', 'Politische Bildung und klare Haltung gegen Extremismus und Hass sind Pflicht in der Schule; ein Gedenkstättenbesuch wird verpflichtend.', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=52', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9041, 22, 11, 'MV', 'Staatliche NGO-Förderung nur bei schriftlicher Verpflichtung auf die Grundordnung und Distanzierung vom Antisemitismus.', '{2204}', 8988, 1, 2, null, 'Verhindert, dass öffentliche Mittel extremistische Strukturen stützen; solche Förderungen sind aber selten. Unbestimmte Klauseln wurden gerichtlich beanstandet (VG Dresden 2012), rechtssichere Fassung ist möglich. Wirkung kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=37', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9042, 22, 11, 'MV', 'Ein Landesprogramm soll die Jugend- und Straßensozialarbeit stärken, um niedrigschwellig auf neue Problemlagen zu reagieren.', '{2201}', 8987, 1, 2, null, 'Bietet Jugendlichen Anlaufstellen und Alternativen zu Milieus, ist aber nicht gezielt auf Radikalisierung ausgerichtet; Fachkräfte sind knapp. Spezifische Wirkung auf Extremismus kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=97', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9043, 22, 11, 'MV', 'Werteerziehung und Respekt gegenüber der Umwelt sind Teil des schulischen Auftrags.', '{2206}', 8992, 1, 3, null, 'Programme zum sozialen Lernen verbessern Sozialverhalten und Einstellungen nachweislich. Die Maßnahmen bleiben aber meist unbestimmt, und ein Effekt auf politische Toleranz ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=51', 'https://ojp.gov/ncjrs/virtual-library/abstracts/impact-enhancing-students-social-and-emotional-learning-meta', 'belegt', '2026-10-10', false, true, 'blind'),
  (9044, 22, 11, 'ST', 'Förderprogramm für Projekte, in denen Grundschulkinder demokratisches Zusammenleben im Unterricht erleben; Demokratiebildung an Schulen stärken', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=59', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9045, 22, 11, 'ST', 'Förderung von Initiativen, die Begegnung und Dialog ermöglichen und respektvolles Miteinander in religiöser Vielfalt stärken (Gesprächs- und Respektkultur)', '{2205,2206}', 9000, 2, 3, null, 'Kontakt verringert Vorurteile laut Metaanalysen und Feldexperimenten. Dagegen: neuere vorregistrierte Studien finden kleinere Effekte, die oft auf die getroffenen Personen begrenzt bleiben.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=73', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9046, 22, 11, 'ST', 'Gegenseitiges Kennenlernen und Achten zwischen Religionen und Einwohnern fördern; Intoleranz bekämpfen', '{2206}', 9000, 2, 3, null, 'Kontakt verringert Vorurteile laut Metaanalysen und Feldexperimenten. Dagegen: neuere vorregistrierte Studien finden kleinere Effekte, die oft auf die getroffenen Personen begrenzt bleiben.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=74', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9047, 22, 11, 'ST', 'Förderung offener Kanäle und nichtkommerzieller Lokalradios, die Zugang zu Medien und Vielfalt vor Ort sichern', '{2206}', 9003, 2, 3, null, 'Schließungen von Lokalzeitungen erhöhen nachweislich politische Polarisierung, auch in Deutschland. Dagegen: ob Förderung Schließungen verhindert, ist offen; Umfang der Förderung entscheidet.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=37', 'https://ideas.repec.org/a/cup/bjposi/v54y2024i4p1256-1275_12.html', 'belegt', '2026-10-10', false, true, 'blind'),
  (9048, 22, 12, null, 'Programme zur Medien- und Nachrichtenkompetenz für alle Altersgruppen ausbauen', '{2202}', 9007, 2, 2, null, 'Experimente zeigen, dass Medienkompetenz-Trainings die Unterscheidung von Falsch- und Qualitätsnachrichten verbessern. Effekte sind moderat und schwinden; Schulbildung liegt bei den Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=49', 'https://collaborate.princeton.edu/en/publications/a-digital-media-literacy-intervention-increases-discernment-betwe/', 'belegt', '2026-10-10', false, true, 'blind'),
  (9049, 22, 12, null, 'Verpflichtende Faktencheck-Tools auf großen Plattformen und Durchsetzung der Bot-Kennzeichnung', '{2202}', 9009, 1, 1, null, 'Faktenchecks korrigieren Fehlinformationen moderat, bei politisch Überzeugten schwächer; Desinformation ist nicht gleich extremistischer Inhalt. Hängt von EU-Entscheidungen ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=50', 'https://cris.haifa.ac.il/en/publications/fact-checking-a-meta-analysis-of-what-works-and-for-whom/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9050, 22, 12, null, 'Bürgerräte als festen Bestandteil der Demokratie etablieren', '{2203}', 9010, 2, 3, null, 'Deliberation senkte im Feldexperiment affektive Polarisierung deutlich und kann Vertrauen stärken. Dagegen: erreicht direkt nur wenige; Wirkung auf die Gesamtbevölkerung uneinheitlich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', 'https://deliberation.stanford.edu/publications/journal-articles/deliberation-antidote-extreme-partisan-polarization-reflections', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9051, 22, 12, null, 'Bildungsangebote fördern, die demokratische Werte vermitteln', '{2204}', 9020, 1, 3, null, 'Bildungsarbeit setzt an Ideologien an; der Bund fördert bereits. Dagegen: Wirkung von Gedenkstättenbesuchen und Bildungsangeboten auf Einstellungen schwer belegbar, Erwartungen laut Forschung oft überzogen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=40', 'https://www.news4teachers.de/2023/01/holocaust-gedenktag-debatte-um-verpflichtende-gedenkstaetten-besuche-von-schuelern-was-bringen-sie-wirklich/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9052, 22, 12, null, 'Bessere historische Bildung und Strukturen historischer Bildung fördern', '{2204}', 9020, 1, 3, null, 'Bildungsarbeit setzt an Ideologien an; der Bund fördert bereits. Dagegen: Wirkung von Gedenkstättenbesuchen und Bildungsangeboten auf Einstellungen schwer belegbar, Erwartungen laut Forschung oft überzogen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=40', 'https://www.news4teachers.de/2023/01/holocaust-gedenktag-debatte-um-verpflichtende-gedenkstaetten-besuche-von-schuelern-was-bringen-sie-wirklich/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9053, 22, 12, null, 'Interreligiösen Dialog fördern', '{2205}', null, 1, 3, null, 'Interreligiöser Dialog kann über Kontakt Vorurteile abbauen. Dagegen: unbestimmt, auf Bundesebene erreicht er wenige Menschen direkt; Kontakteffekte bleiben oft klein.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, 'gemischt', '2026-10-10', false, true, 'blind'),
  (9054, 22, 12, 'BE', 'Kompetenzzentrum für Ausstiegs- und Distanzierungsarbeit zu Islamismus und Rechtsextremismus einrichten', '{2201}', 8984, 2, 3, null, 'Setzt direkt an Bindungen ans Milieu an; Review zeigt Erfolge v. a. bei Ausstieg mit Bildung, Arbeit, sozialer Einbindung. Dagegen: wenige belastbare Wirkungsevaluationen, Deradikalisierung im engeren Sinn wirkt im Schnitt schwächer.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=29', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/1027', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9055, 22, 12, 'BE', 'Rechtsextreme Jugendkultur mit gezielten Präventionsprogrammen begegnen', '{2201}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=29', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9056, 22, 12, 'BE', 'Zusammenarbeit von Sicherheitsbehörden mit zivilgesellschaftlichen Akteuren in der Extremismusbekämpfung stärken', '{2201}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=29', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9057, 22, 12, 'BE', 'Träger politischer Bildung auskömmlich finanzieren und ihre inhaltliche Unabhängigkeit sichern', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=29', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9058, 22, 12, 'BE', 'Demokratisierungsgrad der Schulen messen und Mittel für Demokratisierungsprojekte bereitstellen', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9059, 22, 12, 'BE', 'Konsequent gegen Antisemitismus, Rassismus und menschenverachtende Ideologie an Hochschulen vorgehen und Prävention stärken', '{2204}', 8991, 1, 3, null, 'Setzt an Vorurteilen und Überlegenheitsdenken an; Begegnungsformate wirken eher. Dagegen: Metaanalyse findet bei vielen Vorurteilsprogrammen nur kurzfristige, kleine Effekte und Hinweise auf Publikationsbias.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=45', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9060, 22, 12, 'BE', 'Lehrplan, Curricula und Lehrmaterialien queer- und rassismussensibel überarbeiten', '{2204}', 8991, 1, 3, null, 'Setzt an Vorurteilen und Überlegenheitsdenken an; Begegnungsformate wirken eher. Dagegen: Metaanalyse findet bei vielen Vorurteilsprogrammen nur kurzfristige, kleine Effekte und Hinweise auf Publikationsbias.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9061, 22, 12, 'BE', 'Fortbildungen zu Rassismus und Postkolonialismus sowie diskriminierungskritische Module in der Ausbildung pädagogischer Fachkräfte', '{2204}', 8995, 1, 3, null, 'Trainings verbessern Wissen dauerhaft, Einstellungseffekte schwinden aber ohne Einbettung. Erreicht Multiplikatoren, wirkt auf die Bevölkerung nur mittelbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9062, 22, 12, 'BE', 'Rassismusprävention gemeinsam mit Communities weiterentwickeln und in einem Landeskonzept Antidiskriminierung bündeln', '{2204}', 8986, 1, 3, null, 'Kann Prävention bündeln und Lücken schließen; ohne zusätzliche Angebote bleibt die Wirkung aber mittelbar und hängt von der späteren Umsetzung ab. Zur Wirkung solcher Strategien gibt es kaum Studien.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=48', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9063, 22, 12, 'BE', 'Empathie als Thema in einem Wahlpflichtfach einführen und Fähigkeit zum Kompromiss fördern', '{2206}', 8992, 1, 3, null, 'Programme zum sozialen Lernen verbessern Sozialverhalten und Einstellungen nachweislich. Die Maßnahmen bleiben aber meist unbestimmt, und ein Effekt auf politische Toleranz ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://ojp.gov/ncjrs/virtual-library/abstracts/impact-enhancing-students-social-and-emotional-learning-meta', 'belegt', '2026-10-10', false, true, 'blind'),
  (9064, 22, 12, 'BE', 'Schülervertretungen und Klassenrat als Instrumente für Konfliktlösung stärken', '{2205}', 8994, 1, 3, null, 'Mitwirkung in Schulgremien hängt in Panelstudien mit politischer Wirksamkeit und Beteiligung zusammen und übt Streitkultur. Dagegen: Effekt auf Eskalation politischer Gespräche nicht direkt untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9065, 22, 12, 'BE', 'Vor-Ort-Dialoge der Senatsmitglieder und frühzeitige Informationsveranstaltungen bei Bau- und Infrastrukturmaßnahmen', '{2205}', 8998, 1, 3, null, 'Kann Kontrollverlust und Gefühl der Bevormundung mindern. Dagegen: Wirkung hängt davon ab, ob Ergebnisse berücksichtigt werden; ohne Folgen droht Enttäuschung. Kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=29', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9066, 22, 12, 'BE', 'Ressortübergreifende Programme zur gewaltfreien Konfliktlösung und Prävention in den Kiezen', '{2204,2205}', null, 1, 3, null, 'Programme zur gewaltfreien Konfliktlösung können Gewaltrechtfertigung und Eskalation mindern. Dagegen: unbestimmt, Bezug zu politischen Konflikten offen; kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-10', false, true, 'blind'),
