  (9068, 22, 12, 'MV', 'Gewalt- und Extremismusprävention an Schulen weiter stärken', '{2201}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9069, 22, 12, 'MV', 'Demokratiebildung als Bestandteil von Studium, Referendariat, Fortbildung und Schulleitungsqualifizierung verankern', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=66', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9070, 22, 12, 'MV', 'Verfassungstreue als Voraussetzung für Tätigkeit in der öffentlichen Verwaltung sicherstellen', '{2204}', 8996, 1, 3, null, 'Verhindert, dass Staatsbedienstete extremistische Ideologien weitertragen, und schützt Vertrauen in Institutionen. Ändert Einstellungen in der Bevölkerung kaum; Wirkung nicht untersucht.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=42', null, 'offen', '2026-10-10', false, true, 'blind'),
