  (9072, 22, 12, 'MV', 'Kommunen dabei unterstützen, Beteiligungsverfahren zu etablieren', '{2205}', 8998, 1, 3, null, 'Kann Kontrollverlust und Gefühl der Bevormundung mindern. Dagegen: Wirkung hängt davon ab, ob Ergebnisse berücksichtigt werden; ohne Folgen droht Enttäuschung. Kaum untersucht.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=43', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9073, 22, 12, 'MV', 'Qualifizierte Volksbefragung einführen', '{2205}', 8999, 1, 1, null, 'Verfügbare Volksrechte gehen in der Schweiz mit mehr Vertrauen einher, häufige Nutzung teils mit weniger. Quoren stehen meist in der Landesverfassung, Änderung braucht Zweidrittelmehrheit.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=6', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'gemischt', '2026-10-10', false, true, 'blind'),
