  (9075, 22, 12, 'ST', 'Landeszentrale für politische Bildung personell und finanziell absichern und aufstocken.', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=20', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9076, 22, 12, 'ST', 'Anliegen der Bauernproteste in einen strukturierten Dialog überführen.', '{2205}', 8998, 1, 3, null, 'Kann Kontrollverlust und Gefühl der Bevormundung mindern. Dagegen: Wirkung hängt davon ab, ob Ergebnisse berücksichtigt werden; ohne Folgen droht Enttäuschung. Kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=45', null, 'offen', '2026-10-10', false, true, 'blind'),
