  (9078, 22, 12, 'ST', 'Pädagogisch begleitete Freiräume, Jugendclubs und selbstorganisierte Räume weiter stärken.', '{2201}', 8987, 1, 2, null, 'Bietet Jugendlichen Anlaufstellen und Alternativen zu Milieus, ist aber nicht gezielt auf Radikalisierung ausgerichtet; Fachkräfte sind knapp. Spezifische Wirkung auf Extremismus kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=26', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9079, 22, 13, null, 'Große Medienplattformen auf EU-Ebene in die Pflicht nehmen, Maßnahmen gegen Verbreitung von Desinformation zu ergreifen', '{2202}', 9009, 1, 1, null, 'Faktenchecks korrigieren Fehlinformationen moderat, bei politisch Überzeugten schwächer; Desinformation ist nicht gleich extremistischer Inhalt. Hängt von EU-Entscheidungen ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=140', 'https://cris.haifa.ac.il/en/publications/fact-checking-a-meta-analysis-of-what-works-and-for-whom/', 'gemischt', '2026-10-10', false, true, 'blind'),
