  (9095, 22, 13, 'BE', 'Moderierte Debattenräume an Hochschulen und Dialogförderung in Zeiten politischer Unsicherheit', '{2205}', 9000, 2, 3, null, 'Kontakt verringert Vorurteile laut Metaanalysen und Feldexperimenten. Dagegen: neuere vorregistrierte Studien finden kleinere Effekte, die oft auf die getroffenen Personen begrenzt bleiben.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=199', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
