  (9100, 22, 13, 'BE', 'Verpflichtende Vermittlung von Demokratiebildung, Diskriminierungskritik und kommunikativen Kompetenzen in Aus- und Fortbildung der Sicherheitsbehörden', '{2204}', 8995, 1, 3, null, 'Trainings verbessern Wissen dauerhaft, Einstellungseffekte schwinden aber ohne Einbettung. Erreicht Multiplikatoren, wirkt auf die Bevölkerung nur mittelbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=226', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9101, 22, 13, 'BE', 'Stärkung der Deradikalisierungsarbeit und der Beratungsstellen gegen Verschwörungsideologien sowie Ausbau der Arbeit mit Jugendlichen und Männern', '{2201}', 8984, 2, 3, null, 'Setzt direkt an Bindungen ans Milieu an; Review zeigt Erfolge v. a. bei Ausstieg mit Bildung, Arbeit, sozialer Einbindung. Dagegen: wenige belastbare Wirkungsevaluationen, Deradikalisierung im engeren Sinn wirkt im Schnitt schwächer.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=230', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/1027', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9102, 22, 13, 'BE', 'Bundesratsinitiative: Bekenntnis der Schöffen und ehrenamtlichen Richter zur freiheitlich-demokratischen Grundordnung', '{2204}', null, 1, 2, null, 'Hält Verfassungsfeinde aus Laiengerichten fern und schützt Vertrauen in die Justiz. Ändert Einstellungen kaum; Bundesratsinitiative braucht Mehrheiten im Bund.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=241', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9103, 22, 13, 'BE', 'Ausbau der Fortbildungsangebote für Lehrkräfte und Schulen, Vorurteile und Respekt unter Schüler*innen zu befördern', '{2206}', 8992, 1, 3, null, 'Programme zum sozialen Lernen verbessern Sozialverhalten und Einstellungen nachweislich. Die Maßnahmen bleiben aber meist unbestimmt, und ein Effekt auf politische Toleranz ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=193', 'https://ojp.gov/ncjrs/virtual-library/abstracts/impact-enhancing-students-social-and-emotional-learning-meta', 'belegt', '2026-10-10', false, true, 'blind'),
  (9104, 22, 13, 'MV', 'Demokratiebildung als Querschnittsaufgabe in Ausbildung und Lehrplänen verankern, auch zu Desinformation', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9105, 22, 13, 'MV', 'Landeszentrale für politische Bildung gesetzlich absichern und Regionalzentren für Demokratie stärken', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://gruene-mv.de/?wpdmdl=33772#page=90', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9106, 22, 13, 'MV', 'Unabhängige Forschungsstelle Demokratie einrichten, die Analysen demokratiefeindlicher Bestrebungen veröffentlicht', '{2204}', null, 1, 3, null, 'Öffentlich zugängliche Analysen und Bildungsangebote zu demokratiefeindlichen Bestrebungen setzen an Ideologien an; Wirkung nur mittelbar und nicht untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=79', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9107, 22, 13, 'MV', 'Bürger*innenräte auf Landes- und Kommunalebene für gemeinsam getragene Entscheidungen einführen', '{2205}', 8997, 2, 3, null, 'Deliberation senkte im Feldexperiment affektive Polarisierung deutlich und gibt Mitsprache. Dagegen: erreicht direkt nur wenige; Effekte auf Vertrauen der übrigen Bevölkerung uneinheitlich.', 'https://gruene-mv.de/?wpdmdl=33772#page=67', 'https://deliberation.stanford.edu/publications/journal-articles/deliberation-antidote-extreme-partisan-polarization-reflections', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9108, 22, 13, 'MV', 'Soziale Präventionsarbeit in Kommunen finanziell stärken, etwa Streetwork und Jugendclubs', '{2201}', 8987, 1, 2, null, 'Bietet Jugendlichen Anlaufstellen und Alternativen zu Milieus, ist aber nicht gezielt auf Radikalisierung ausgerichtet; Fachkräfte sind knapp. Spezifische Wirkung auf Extremismus kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=76', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9109, 22, 13, 'ST', 'Stärkere Unterstützung von Beratungsstellen und zivilgesellschaftlichen Akteuren in der Extremismusprävention in der Fläche', '{2201}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=40', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9110, 22, 13, 'ST', 'Kitas zu „Kinderstuben der Demokratie“ machen, Beteiligung in der Kita fördern; Prävention von Radikalisierung', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=58', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9111, 22, 13, 'ST', 'Demokratiebildung als fächerübergreifendes Leitprinzip im Schulalltag, Schülermitbestimmung stärken', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9112, 22, 13, 'ST', 'Verpflichtender Sozialkundeunterricht über die gesamte Schulzeit; politische Bildung ausbauen', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=37', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9113, 22, 13, 'ST', 'Aus- und Fortbildung der Polizei auf demokratische Werte und Antidiskriminierung ausrichten; regelmäßige Fortbildungen gegen Extremismus vorbeugen', '{2204}', 8995, 1, 3, null, 'Trainings verbessern Wissen dauerhaft, Einstellungseffekte schwinden aber ohne Einbettung. Erreicht Multiplikatoren, wirkt auf die Bevölkerung nur mittelbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9114, 22, 13, 'ST', 'Landes-Demokratiefördergesetz: Projekte gegen Extremismus, Hass und Gewalt dauerhaft und unabhängig von Haushaltsentscheidungen fördern', '{2204}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=74', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9115, 22, 13, 'ST', 'Landeszentrale für politische Bildung per eigenem Landesgesetz unabhängig absichern', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=74', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9116, 22, 13, 'ST', 'Projekte stärken, die gegen Rassismus, Islamfeindlichkeit, Queerfeindlichkeit und andere gruppenbezogene Menschenfeindlichkeit arbeiten', '{2204}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=75', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9117, 22, 13, 'ST', 'Disziplinarverfahren gegen Verfassungsfeinde im öffentlichen Dienst zentral bündeln und personell besser ausstatten', '{2204}', 8996, 1, 3, null, 'Verhindert, dass Staatsbedienstete extremistische Ideologien weitertragen, und schützt Vertrauen in Institutionen. Ändert Einstellungen in der Bevölkerung kaum; Wirkung nicht untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=40', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9118, 22, 13, 'ST', 'Prävention und Bildung gegen Rassismus, Antifeminismus und gruppenbezogene Menschenfeindlichkeit; Bildungsarbeit und politische Jugendbildung stärken', '{2204}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=41', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9119, 22, 13, 'ST', 'Dialogformat „Parlament der Dörfer“ einführen, das den Austausch zwischen Dörfern und Politik ermöglicht', '{2205}', 8998, 1, 3, null, 'Kann Kontrollverlust und Gefühl der Bevormundung mindern. Dagegen: Wirkung hängt davon ab, ob Ergebnisse berücksichtigt werden; ohne Folgen droht Enttäuschung. Kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=36', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9120, 22, 13, 'ST', 'Medienangebote in Dörfern und Kleinstädten fördern, damit lokale Debattenkultur und Berichterstattung erhalten bleiben', '{2205}', 9003, 2, 3, null, 'Schließungen von Lokalzeitungen erhöhen nachweislich politische Polarisierung, auch in Deutschland. Dagegen: ob Förderung Schließungen verhindert, ist offen; Umfang der Förderung entscheidet.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=53', 'https://ideas.repec.org/a/cup/bjposi/v54y2024i4p1256-1275_12.html', 'belegt', '2026-10-10', false, true, 'blind'),
  (9121, 22, 13, 'ST', 'Kommunen befähigen, Mitsprache über Bürgerräte, Beteiligungshaushalte und digitale Dialogformate aktiv zu gestalten', '{2205}', 8998, 1, 3, null, 'Kann Kontrollverlust und Gefühl der Bevormundung mindern. Dagegen: Wirkung hängt davon ab, ob Ergebnisse berücksichtigt werden; ohne Folgen droht Enttäuschung. Kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=38', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9122, 22, 14, null, 'Lehrpläne modernisieren mit mehr Raum für Demokratie, Politik und Medienkompetenz', '{2202,2204}', null, 1, 1, null, 'Mehr Demokratie- und Medienbildung im Lehrplan setzt an Ideologie und Medienkontakt an. Lehrpläne sind aber Ländersache; Wirkung schulischer Programme moderat.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-10-10', false, true, 'blind'),
  (9123, 22, 14, null, 'Verpflichtende Besuche von Gedenkstätte und Synagoge sowie Auseinandersetzung mit Antisemitismus im Schulunterricht', '{2204}', 9021, 1, 2, null, 'Kann historisches Bewusstsein stärken. Dagegen: Pflichtbesuche wirken laut Forschung nur mit guter Vor- und Nachbereitung, sonst teils Abwehr; Schule ist Ländersache, der Bund kann nur fördern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', 'https://www.news4teachers.de/2023/01/holocaust-gedenktag-debatte-um-verpflichtende-gedenkstaetten-besuche-von-schuelern-was-bringen-sie-wirklich/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9124, 22, 14, null, 'Kein Platz im öffentlichen Dienst für Menschen mit erwiesenen verfassungsfeindlichen Einstellungen', '{2204}', 9022, 1, 3, null, 'Verhindert, dass Staatsbedienstete extremistische Ideologien weitertragen. Ändert Einstellungen in der Bevölkerung kaum; Wirkung nicht untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9125, 22, 14, null, 'IHRA-Arbeitsdefinition von Antisemitismus in Behörden etablieren und Grundlage von Fortbildungen für Beamtinnen und Beamte machen', '{2204}', null, 1, 3, null, 'Einheitliche Definition und Fortbildungen schärfen den Blick von Behörden für Antisemitismus. Wirkt auf Einstellungen in der Bevölkerung nur mittelbar; Wirkung nicht untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9126, 22, 14, null, 'Islamischen Religionsunterricht frei von islamistischer oder ausländisch gesteuerter Einflussnahme anbieten', '{2201}', 9019, 1, 2, null, 'Kann ausländische und islamistische Einflussnahme auf Gemeinden begrenzen. Dagegen: Pflichten berühren Religionsfreiheit und Länderzuständigkeit; Wirkung kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9127, 22, 14, null, 'Ausbildung von Imamen und islamischen Religionslehrern an deutschen Universitäten ausbauen', '{2201}', 9019, 1, 2, null, 'Kann ausländische und islamistische Einflussnahme auf Gemeinden begrenzen. Dagegen: Pflichten berühren Religionsfreiheit und Länderzuständigkeit; Wirkung kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9128, 22, 14, null, 'Verbände, die Islamismus verharmlosen oder Antisemitismus nicht verurteilen, sind keine Partner der Religionspolitik', '{2201}', 9017, 1, 2, null, 'Verhindert, dass staatliche Mittel und Anerkennung extremistische Milieus stützen. Dagegen: rechtssichere, bestimmte Kriterien nötig; Wirkung auf Einstellungen nicht untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9129, 22, 14, null, 'Parlamentarischer Untersuchungsausschuss zur Aufarbeitung der Corona-Maßnahmen für Aufklärung und Transparenz', '{2203}', null, 1, 3, null, 'Aufarbeitung kann Vertrauen bei Menschen stärken, die sich in der Pandemie unfair behandelt fühlten. Dagegen: Wirkung hängt vom Verlauf ab und ist nicht untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9130, 22, 14, 'BE', 'Aussteigerprogramme und Vernetzung staatlicher Stellen mit Initiativen für eine ursachenorientierte Kriminalprävention gegen Extremismus', '{2201}', 8984, 2, 3, null, 'Setzt direkt an Bindungen ans Milieu an; Review zeigt Erfolge v. a. bei Ausstieg mit Bildung, Arbeit, sozialer Einbindung. Dagegen: wenige belastbare Wirkungsevaluationen, Deradikalisierung im engeren Sinn wirkt im Schnitt schwächer.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=66', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/1027', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9131, 22, 14, 'BE', 'Verstärkter Einsatz von Jugend- und Sozialarbeit sowie Streetwork als verlässliche Anlaufstelle', '{2201}', 8987, 1, 2, null, 'Bietet Jugendlichen Anlaufstellen und Alternativen zu Milieus, ist aber nicht gezielt auf Radikalisierung ausgerichtet; Fachkräfte sind knapp. Spezifische Wirkung auf Extremismus kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9132, 22, 14, 'BE', 'Bildungsprogramme gegen Antisemitismus in Schulen verbindlich verankern, mit Begegnungsformaten', '{2204}', 8991, 1, 3, null, 'Setzt an Vorurteilen und Überlegenheitsdenken an; Begegnungsformate wirken eher. Dagegen: Metaanalyse findet bei vielen Vorurteilsprogrammen nur kurzfristige, kleine Effekte und Hinweise auf Publikationsbias.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=79', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9133, 22, 14, 'BE', 'Kita-Besuchspflicht für Kinder von Asylbewerbern, um Sprache und Werte zu vermitteln, strafbewehrt', '{2204}', null, 1, 1, null, 'Frühe Kita-Bildung kann Sprache und Werte vermitteln. Eine strafbewehrte Pflicht nur für eine Gruppe ist rechtlich (Gleichbehandlung, Elternrecht) schwer haltbar; Wirkung auf Einstellungen offen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=97', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9134, 22, 14, 'BE', 'Austausch mit israelischen Schulen und Partnerstadt sowie Dialog zu Glauben und Demokratie ausbauen', '{2205,2206}', 9000, 2, 3, null, 'Kontakt verringert Vorurteile laut Metaanalysen und Feldexperimenten. Dagegen: neuere vorregistrierte Studien finden kleinere Effekte, die oft auf die getroffenen Personen begrenzt bleiben.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=79', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9135, 22, 14, 'MV', 'Bestehende Präventionsprogramme überprüfen und an aktuelle Herausforderungen anpassen', '{2201}', 8986, 1, 3, null, 'Kann Prävention bündeln und Lücken schließen; ohne zusätzliche Angebote bleibt die Wirkung aber mittelbar und hängt von der späteren Umsetzung ab. Zur Wirkung solcher Strategien gibt es kaum Studien.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=145', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9136, 22, 14, 'MV', 'Ehrenamt im Kampf gegen Extremismus besser fördern und in staatliche Programme integrieren', '{2201}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=145', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9137, 22, 14, 'MV', 'Landeseigene Gedenkstätten unterstützen, die Bildungsarbeit zur SED-Diktatur leisten', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=120', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9138, 22, 14, 'MV', 'Integration durch Sprache, Arbeit und Werte fördern mit verbindlichen Kursen und Bekenntnis zum Grundgesetz', '{2204}', 9006, 1, 1, null, 'Vermittelt demokratische Grundwerte; Integrationskurse regelt aber der Bund, das Land kann kaum verpflichten. Wirkung auf Einstellungen kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=144', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9139, 22, 14, 'MV', 'Offene Debattenkultur an Hochschulen auch mit schwer erträglichen Meinungen sichern', '{2205}', 9001, 1, 3, null, 'Kann das Gefühl verringern, Positionen würden sanktioniert, und Streit an Hochschulen versachlichen. Dagegen: bestehender Grundrechtsschutz, unklare Reichweite; Wirkung kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=113', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9140, 22, 14, 'MV', 'Offene Debatten im Hochschulraum gegen Konformitätsdruck stärken', '{2205}', 9001, 1, 3, null, 'Kann das Gefühl verringern, Positionen würden sanktioniert, und Streit an Hochschulen versachlichen. Dagegen: bestehender Grundrechtsschutz, unklare Reichweite; Wirkung kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=113', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9141, 22, 14, 'MV', 'Digitale-Dienste-Gesetz ändern: Löschen von Inhalten unterhalb der Strafbarkeitsschwelle durch Plattformen verbieten', '{2205}', 9004, 0, 1, null, 'Studien zeigen, dass Sperren extremistischer Accounts deren Reichweite senkt; weniger Moderation erhöht eher den Kontakt mit solchen Inhalten. Plattformrecht ist durch den DSA europäisch geregelt.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=151', 'https://www.rutgers.edu/news/permanent-twitter-ban-extremist-influencers-can-detoxify-social-media', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9142, 22, 14, 'ST', 'Hochschulen: Bekenntnis zur freiheitlich-demokratischen Grundordnung und zum Grundgesetz als Voraussetzung.', '{2204}', null, 1, 1, null, 'Soll Ideologien an Hochschulen begrenzen. Ein Bekenntnis als Zugangsvoraussetzung berührt Berufs- und Wissenschaftsfreiheit; Wirkung auf Einstellungen nicht untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=33', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9143, 22, 14, 'ST', 'Wiedereinführung des Leistungskurses Geschichte an Gymnasien, um demokratisches Bewusstsein zu stärken.', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=26', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9144, 22, 14, 'ST', 'In Jugendarbeit und Schule Diskriminierung entgegenwirken und für Toleranz und Akzeptanz aufklären.', '{2206}', 8992, 1, 3, null, 'Programme zum sozialen Lernen verbessern Sozialverhalten und Einstellungen nachweislich. Die Maßnahmen bleiben aber meist unbestimmt, und ein Effekt auf politische Toleranz ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', 'https://ojp.gov/ncjrs/virtual-library/abstracts/impact-enhancing-students-social-and-emotional-learning-meta', 'belegt', '2026-10-10', false, true, 'blind'),
  (9145, 22, 15, null, 'Volksentscheide nach Schweizer Vorbild auch auf Bundesebene einführen', '{2203}', 9011, 1, 1, null, 'Verfügbare Volksrechte gehen mit mehr Institutionenvertrauen einher, häufige Nutzung teils mit weniger. Erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=131', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9146, 22, 15, null, 'EU-Plattformregulierung (DSA) ablehnen und das Netzwerkdurchsetzungsgesetz zurückbauen', '{2202}', null, 0, 0, null, 'Weniger Moderation erhöht eher den Kontakt mit extremistischen Inhalten; Sperren senken laut Studien deren Reichweite. Der DSA ist unmittelbar geltendes EU-Recht, eine Nichtanwendung wäre EU-rechtswidrig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=50', null, 'gemischt', '2026-10-10', false, true, 'blind'),
  (9147, 22, 15, null, 'Schülern erlauben, ihre politischen Ansichten ohne Repressionen oder Diskriminierung zu äußern', '{2205}', 9016, 1, 1, null, 'Offenes Klassenklima kann Vertrauen und Toleranz stützen; Neutralitäts- und Kontroversitätsgebot gelten bereits. Schulrecht ist Ländersache.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=161', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9148, 22, 15, null, 'Schule frei von politischer Propaganda; Schüler sollen eigene Denkweisen ohne Lehrplanvorgaben entwickeln', '{2206}', 9016, 1, 1, null, 'Offenes Klassenklima kann Vertrauen und Toleranz stützen; Neutralitäts- und Kontroversitätsgebot gelten bereits. Schulrecht ist Ländersache.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=161', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9149, 22, 15, null, 'Lehrkräfte zur politischen Neutralität verpflichten und Wahlaufrufe im Unterricht untersagen', '{2206}', 9016, 1, 1, null, 'Offenes Klassenklima kann Vertrauen und Toleranz stützen; Neutralitäts- und Kontroversitätsgebot gelten bereits. Schulrecht ist Ländersache.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=161', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9150, 22, 15, null, 'Mandatszeiten für Abgeordnete und Bundeskanzler begrenzen', '{2203}', 9014, 1, 1, null, 'Soll Bürgernähe und Vertrauen stärken; Wirkung auf Institutionenvertrauen nicht untersucht. Erfordert Grundgesetzänderungen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=138', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9151, 22, 15, null, 'Justizwahlausschuss einrichten und Richter nach Qualifikation besetzen', '{2203}', 9013, 1, 2, null, 'Kann Vertrauen in eine unparteiische Justiz stärken. Dagegen: Zusammenhang mit radikalen Einstellungen nur mittelbar; teils Grundgesetz- und Länderfragen berührt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=138', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9152, 22, 15, null, 'Weisungsgebundenheit der Staatsanwaltschaft abschaffen', '{2203}', 9013, 1, 2, null, 'Kann Vertrauen in eine unparteiische Justiz stärken. Dagegen: Zusammenhang mit radikalen Einstellungen nur mittelbar; teils Grundgesetz- und Länderfragen berührt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=139', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9153, 22, 15, null, 'Freie Listenwahl mit Kumulieren und Streichen von Kandidaten einführen', '{2203}', null, 1, 3, null, 'Mehr Einfluss der Wähler auf Personen kann Vertrauen stärken; Wirkung auf Institutionenvertrauen kaum untersucht. Per Bundeswahlgesetz möglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=136', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9154, 22, 15, null, 'Bundespräsident direkt vom Volk wählen lassen', '{2203}', 9014, 1, 1, null, 'Soll Bürgernähe und Vertrauen stärken; Wirkung auf Institutionenvertrauen nicht untersucht. Erfordert Grundgesetzänderungen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=135', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9155, 22, 15, null, 'Entscheidungen der Parteien in eigener Sache unter Rechnungshof-Kontrolle stellen und öffentlich machen', '{2203}', 9012, 1, 3, null, 'Setzt am geringen Vertrauen in Institutionen an, indem Interessenkonflikte begrenzt werden. Dagegen: Wirkung auf Vertrauen und radikale Einstellungen kaum untersucht, eher mittelbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=137', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9156, 22, 15, null, 'Hinweisgeberschutzgesetz so überarbeiten, dass auch staatliches Fehlverhalten erfasst wird', '{2203}', 9012, 1, 3, null, 'Setzt am geringen Vertrauen in Institutionen an, indem Interessenkonflikte begrenzt werden. Dagegen: Wirkung auf Vertrauen und radikale Einstellungen kaum untersucht, eher mittelbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=140', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9157, 22, 15, null, 'Beteiligungen von Parteien an Medienunternehmen verbieten', '{2203}', null, 1, 1, null, 'Soll Unabhängigkeit der Medien und Vertrauen stärken; Wirkung nicht untersucht. Ein vollständiges Beteiligungsverbot für Parteien ist verfassungsrechtlich problematisch.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=133', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9158, 22, 15, null, 'Imame: Verfassungsbekenntnis und Ausbildung in Deutschland verlangen', '{2204}', 9019, 1, 2, null, 'Kann ausländische und islamistische Einflussnahme auf Gemeinden begrenzen. Dagegen: Pflichten berühren Religionsfreiheit und Länderzuständigkeit; Wirkung kaum untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=124', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9159, 22, 15, null, 'Vereine und Verbände, die Extremisten unterstützen, von staatlichen Mitteln ausschließen', '{2204}', 9017, 1, 2, null, 'Verhindert, dass staatliche Mittel und Anerkennung extremistische Milieus stützen. Dagegen: rechtssichere, bestimmte Kriterien nötig; Wirkung auf Einstellungen nicht untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=122', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9160, 22, 15, 'BE', 'Förderprogramme für linksextremistische Organisationen und linke Vorfeldorganisationen beenden', '{2201,2204}', 8988, 1, 2, null, 'Verhindert, dass öffentliche Mittel extremistische Strukturen stützen; solche Förderungen sind aber selten. Unbestimmte Klauseln wurden gerichtlich beanstandet (VG Dresden 2012), rechtssichere Fassung ist möglich. Wirkung kaum untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=17', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9161, 22, 15, 'BE', 'Verbot jeglicher Auslandsfinanzierung für Moscheen', '{2201}', null, 1, 1, null, 'Kann ausländische Einflussnahme auf Moscheegemeinden begrenzen. Pauschales Verbot berührt Religionsfreiheit und EU-Kapitalverkehr; Vereinsrecht ist Bundessache. Wirkung nicht untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=24', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9162, 22, 15, 'BE', 'Ende aller Kooperationen mit extremistischen Institutionen', '{2201}', 8988, 1, 2, null, 'Verhindert, dass öffentliche Mittel extremistische Strukturen stützen; solche Förderungen sind aber selten. Unbestimmte Klauseln wurden gerichtlich beanstandet (VG Dresden 2012), rechtssichere Fassung ist möglich. Wirkung kaum untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=24', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9163, 22, 15, 'BE', 'Antisemitismusprävention im Schulunterricht ausbauen und verankern', '{2204}', 8991, 1, 3, null, 'Setzt an Vorurteilen und Überlegenheitsdenken an; Begegnungsformate wirken eher. Dagegen: Metaanalyse findet bei vielen Vorurteilsprogrammen nur kurzfristige, kleine Effekte und Hinweise auf Publikationsbias.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=24', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9164, 22, 15, 'BE', 'Indoktrinationsverbot im Schulunterricht; kontroverse Themen auch in Schulbüchern kontrovers behandeln', '{2206}', 8993, 1, 3, null, 'Ein offenes Klassenklima kann Vertrauen und Toleranz fördern; das Kontroversitätsgebot gilt aber bereits weitgehend. Strengere Neutralität kann Lehrkräfte auch von der Auseinandersetzung mit Extremismus abhalten.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=27', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9165, 22, 15, 'BE', 'Berliner Hochschulen per Gesetz zu einem Kodex Wissenschaftsfreiheit verpflichten', '{2205}', 9001, 1, 3, null, 'Kann das Gefühl verringern, Positionen würden sanktioniert, und Streit an Hochschulen versachlichen. Dagegen: bestehender Grundrechtsschutz, unklare Reichweite; Wirkung kaum untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=35', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9166, 22, 15, 'BE', 'Kulturförderung nicht für Projekte gegen die freiheitlich-demokratische Grundordnung oder mit Antisemitismus-Vorschub', '{2204}', 8988, 1, 2, null, 'Verhindert, dass öffentliche Mittel extremistische Strukturen stützen; solche Förderungen sind aber selten. Unbestimmte Klauseln wurden gerichtlich beanstandet (VG Dresden 2012), rechtssichere Fassung ist möglich. Wirkung kaum untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=86', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9167, 22, 15, 'BE', 'Politische Gesinnung kein Kriterium bei der Bewilligung von Kulturförderung', '{2205}', 8989, 1, 3, null, 'Kann bei Teilen der Bevölkerung das Gefühl von Bevormundung und Ungleichbehandlung mindern. Dagegen: Streichungen schwächen Dokumentation und Präventionsarbeit; Wirkung auf Gesprächskultur nicht untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=90', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9168, 22, 15, 'BE', 'Staatliche Stellen sollen Bürger in sozialen Netzwerken nicht blockieren', '{2205}', 9002, 1, 3, null, 'Kann wahrgenommene Bevormundung und Ungleichbehandlung mindern. Dagegen: Rechtslage schützt nicht strafbare Äußerungen bereits weitgehend; Wirkung nicht untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=90', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9169, 22, 15, 'BE', 'Öffentliche Förderung von Meldestellen für Vorfälle beenden', '{2205}', 8989, 1, 3, null, 'Kann bei Teilen der Bevölkerung das Gefühl von Bevormundung und Ungleichbehandlung mindern. Dagegen: Streichungen schwächen Dokumentation und Präventionsarbeit; Wirkung auf Gesprächskultur nicht untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=77', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9170, 22, 15, 'MV', 'Staatliche Bürgerforen zur Beteiligung einstellen', '{2205}', null, 0, 3, null, 'Streicht Beteiligungsformate; das mag Kritik an Scheinbeteiligung aufgreifen, verringert aber Mitsprache. Keine Hinweise, dass das Eskalation mindert.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=83', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9171, 22, 15, 'MV', 'Quorum für Volksbegehren auf 5 % der Wahlberechtigten senken', '{2205}', 8999, 1, 1, null, 'Verfügbare Volksrechte gehen in der Schweiz mit mehr Vertrauen einher, häufige Nutzung teils mit weniger. Quoren stehen meist in der Landesverfassung, Änderung braucht Zweidrittelmehrheit.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=46', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9172, 22, 15, 'MV', 'Landesförderung für Vorfeldorganisationen, asylpolitische Lobbygruppen und extremistische Strukturen beenden', '{2201}', 8988, 1, 2, null, 'Verhindert, dass öffentliche Mittel extremistische Strukturen stützen; solche Förderungen sind aber selten. Unbestimmte Klauseln wurden gerichtlich beanstandet (VG Dresden 2012), rechtssichere Fassung ist möglich. Wirkung kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=47', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9173, 22, 15, 'MV', 'Islamverbände verpflichten, Meldestellen für radikale und extremistische Tendenzen vorzuhalten', '{2201,2204}', 9005, 1, 2, null, 'Kann Zugang zu Milieus und Verbreitung islamistischer Ideologie erschweren. Dagegen: Pflichten für Verbände berühren Religionsfreiheit; Review warnt vor Nebenwirkungen gruppenbezogener Ansätze.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=53', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9174, 22, 15, 'MV', 'Demokratieklausel: Landesförderung nur bei schriftlicher Verfassungstreue und politischer Neutralität', '{2204}', 8988, 1, 2, null, 'Verhindert, dass öffentliche Mittel extremistische Strukturen stützen; solche Förderungen sind aber selten. Unbestimmte Klauseln wurden gerichtlich beanstandet (VG Dresden 2012), rechtssichere Fassung ist möglich. Wirkung kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=47', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9175, 22, 15, 'MV', 'Sozialkundeunterricht wieder ab der achten Klasse beginnen lassen', '{2204}', null, 1, 3, null, 'Legt den Beginn des Sozialkundeunterrichts fest; ob das mehr oder weniger politische Bildung bedeutet, hängt vom bisherigen Stand ab. Wirkung auf Einstellungen kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9176, 22, 15, 'ST', 'Die Landeszentrale für politische Bildung soll in ihrer jetzigen Form abgeschafft und durch ein anderes Landesinstitut ersetzt werden.', '{2204}', null, 1, 2, null, 'Ersetzt eine bestehende Einrichtung politischer Bildung durch ein neues Institut; ob das Ideologien besser entgegenwirkt, ist nicht belegt, der Umbau kostet Zeit.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=61', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9177, 22, 15, 'ST', 'Eine neue Praxis der Toleranz gegenüber Demonstrationen und nonkonformen Meinungsäußerungen soll etabliert werden.', '{2206}', 9002, 1, 3, null, 'Kann wahrgenommene Bevormundung und Ungleichbehandlung mindern. Dagegen: Rechtslage schützt nicht strafbare Äußerungen bereits weitgehend; Wirkung nicht untersucht.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=133', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9178, 22, 15, 'ST', 'Das Netzwerkdurchsetzungsgesetz soll zurückgenommen und europäische Digitalgesetze überprüft werden.', '{2205}', 9004, 0, 1, null, 'Studien zeigen, dass Sperren extremistischer Accounts deren Reichweite senkt; weniger Moderation erhöht eher den Kontakt mit solchen Inhalten. Plattformrecht ist durch den DSA europäisch geregelt.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=222', 'https://www.rutgers.edu/news/permanent-twitter-ban-extremist-influencers-can-detoxify-social-media', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9179, 22, 16, null, 'KI-Medieninhalte kennzeichnen und Plattformen für Falschinformationen haften lassen', '{2202}', 9009, 1, 1, null, 'Faktenchecks korrigieren Fehlinformationen moderat, bei politisch Überzeugten schwächer; Desinformation ist nicht gleich extremistischer Inhalt. Hängt von EU-Entscheidungen ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=55', 'https://cris.haifa.ac.il/en/publications/fact-checking-a-meta-analysis-of-what-works-and-for-whom/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9180, 22, 16, null, 'Förderung der Medien- und Datenschutzkompetenz von Kindern und Jugendlichen', '{2202}', 9007, 2, 2, null, 'Experimente zeigen, dass Medienkompetenz-Trainings die Unterscheidung von Falsch- und Qualitätsnachrichten verbessern. Effekte sind moderat und schwinden; Schulbildung liegt bei den Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', 'https://collaborate.princeton.edu/en/publications/a-digital-media-literacy-intervention-increases-discernment-betwe/', 'belegt', '2026-10-10', false, true, 'blind'),
  (9181, 22, 16, null, 'Volksinitiativen, Volksbegehren und Volksentscheide auf Bundesebene einführen', '{2203}', 9011, 1, 1, null, 'Verfügbare Volksrechte gehen mit mehr Institutionenvertrauen einher, häufige Nutzung teils mit weniger. Erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9182, 22, 16, null, 'Pflicht, Interessenvertretungen und Sachverständige bei Gesetzentwürfen der Regierung offenzulegen', '{2203}', 9012, 1, 3, null, 'Setzt am geringen Vertrauen in Institutionen an, indem Interessenkonflikte begrenzt werden. Dagegen: Wirkung auf Vertrauen und radikale Einstellungen kaum untersucht, eher mittelbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9183, 22, 16, null, 'Unternehmensspenden an Parteien verbieten und Spenden von Privatpersonen begrenzen', '{2203}', 9012, 1, 3, null, 'Setzt am geringen Vertrauen in Institutionen an, indem Interessenkonflikte begrenzt werden. Dagegen: Wirkung auf Vertrauen und radikale Einstellungen kaum untersucht, eher mittelbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9184, 22, 16, null, 'Dreijährige Karenzzeit für Regierungsmitglieder vor einem Wechsel in befasste Unternehmen', '{2203}', 9012, 1, 3, null, 'Setzt am geringen Vertrauen in Institutionen an, indem Interessenkonflikte begrenzt werden. Dagegen: Wirkung auf Vertrauen und radikale Einstellungen kaum untersucht, eher mittelbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=50', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9185, 22, 16, null, 'Aktives und passives Wahlrecht auf allen Ebenen für langfristig in Deutschland lebende Menschen', '{2203}', null, 1, 1, null, 'Mehr politische Teilhabe kann Gefühl der Benachteiligung mindern. Wahlrecht für Nicht-Deutsche jenseits der EU-Kommunalwahl erfordert laut Verfassungsrechtsprechung eine Grundgesetzänderung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9186, 22, 16, null, 'Politische Bildung, Demokratie und Partizipation früh in Bildungseinrichtungen verankern', '{2204}', 9021, 1, 2, null, 'Kann historisches Bewusstsein stärken. Dagegen: Pflichtbesuche wirken laut Forschung nur mit guter Vor- und Nachbereitung, sonst teils Abwehr; Schule ist Ländersache, der Bund kann nur fördern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', 'https://www.news4teachers.de/2023/01/holocaust-gedenktag-debatte-um-verpflichtende-gedenkstaetten-besuche-von-schuelern-was-bringen-sie-wirklich/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9187, 22, 16, null, 'Dauerhafte Bundesförderung von Gedenkstätten als Bestandteil politischer Bildungsarbeit', '{2204}', 9020, 1, 3, null, 'Bildungsarbeit setzt an Ideologien an; der Bund fördert bereits. Dagegen: Wirkung von Gedenkstättenbesuchen und Bildungsangeboten auf Einstellungen schwer belegbar, Erwartungen laut Forschung oft überzogen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', 'https://www.news4teachers.de/2023/01/holocaust-gedenktag-debatte-um-verpflichtende-gedenkstaetten-besuche-von-schuelern-was-bringen-sie-wirklich/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9188, 22, 16, null, 'Bürgerräte mit zufällig ausgelosten Menschen unterstützen, stärken und fördern', '{2205}', 9010, 2, 3, null, 'Deliberation senkte im Feldexperiment affektive Polarisierung deutlich und kann Vertrauen stärken. Dagegen: erreicht direkt nur wenige; Wirkung auf die Gesamtbevölkerung uneinheitlich.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', 'https://deliberation.stanford.edu/publications/journal-articles/deliberation-antidote-extreme-partisan-polarization-reflections', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9189, 22, 16, null, 'Vermittlung von Werten wie Respekt und Fairness im Sport fördern', '{2206}', null, 1, 2, null, 'Werte wie Respekt und Fairness im Sport können Umgangsformen prägen. Unbestimmt, Bezug zu politischen Auseinandersetzungen gering; Sportförderung liegt weitgehend bei Ländern und Verbänden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=56', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9190, 22, 16, null, 'Stärkere Kontrolle von Medienfusionen zur Erhaltung der Meinungsvielfalt', '{2206}', null, 1, 3, null, 'Medienvielfalt und gemeinnütziger Journalismus können Lokalberichterstattung erhalten, deren Wegfall Polarisierung fördert. Fusionskontrolle wirkt aber nur indirekt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=55', null, 'belegt', '2026-10-10', false, true, 'blind'),
  (9191, 22, 16, 'BE', 'Zielgruppenspezifische Aussteiger*innenprogramme und Maßnahmen ausbauen, die Risikofaktoren wie Gewalterfahrungen und fehlende Integration abmildern.', '{2201}', 8984, 2, 3, null, 'Setzt direkt an Bindungen ans Milieu an; Review zeigt Erfolge v. a. bei Ausstieg mit Bildung, Arbeit, sozialer Einbindung. Dagegen: wenige belastbare Wirkungsevaluationen, Deradikalisierung im engeren Sinn wirkt im Schnitt schwächer.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=180', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/1027', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9192, 22, 16, 'BE', 'Beratung zur Distanzierung von extrem rechten Szenen und sozialräumliche Programme mit Alternativen zu gewaltorientierten Gruppen ausbauen.', '{2201}', 8984, 2, 3, null, 'Setzt direkt an Bindungen ans Milieu an; Review zeigt Erfolge v. a. bei Ausstieg mit Bildung, Arbeit, sozialer Einbindung. Dagegen: wenige belastbare Wirkungsevaluationen, Deradikalisierung im engeren Sinn wirkt im Schnitt schwächer.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=326', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/1027', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9193, 22, 16, 'BE', 'Landesprogramm zur Radikalisierungsprävention und Deradikalisierung stärken.', '{2201}', 8984, 2, 3, null, 'Setzt direkt an Bindungen ans Milieu an; Review zeigt Erfolge v. a. bei Ausstieg mit Bildung, Arbeit, sozialer Einbindung. Dagegen: wenige belastbare Wirkungsevaluationen, Deradikalisierung im engeren Sinn wirkt im Schnitt schwächer.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=288', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/1027', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9194, 22, 16, 'BE', 'Ressortübergreifende Landesstrategie gegen extrem rechte Strukturen und Aktivitäten entwickeln und evaluieren.', '{2201}', 8986, 1, 3, null, 'Kann Prävention bündeln und Lücken schließen; ohne zusätzliche Angebote bleibt die Wirkung aber mittelbar und hängt von der späteren Umsetzung ab. Zur Wirkung solcher Strategien gibt es kaum Studien.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=326', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9195, 22, 16, 'BE', 'Stärkung der bezirklichen Straßensozialarbeit gegen die Ansprache Jugendlicher durch extrem rechte Gruppen.', '{2201}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=180', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9196, 22, 16, 'BE', 'Politische Bildung als Schulfach stärken und an Grundschulen und beruflichen Schulen etablieren.', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=165', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9197, 22, 16, 'BE', 'Außerschulische Bildungs- und Präventionsangebote, u. a. zu Antisemitismusprävention und Gewaltprävention, an Schulen absichern.', '{2204}', 8991, 1, 3, null, 'Setzt an Vorurteilen und Überlegenheitsdenken an; Begegnungsformate wirken eher. Dagegen: Metaanalyse findet bei vielen Vorurteilsprogrammen nur kurzfristige, kleine Effekte und Hinweise auf Publikationsbias.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=163', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9198, 22, 16, 'BE', 'Schulen bei der Auseinandersetzung mit extrem rechten Vorkommnissen unterstützen: Präventions- und Empowermentangebote, Fortbildungen, Leitlinien.', '{2204}', 8985, 2, 3, null, 'Programme, die Schutzfaktoren stärken (Jugendarbeit, Beratung, Bildung), zeigen in den besten Studien Wirkung. Dagegen: Evidenz insgesamt schwach, auf Gruppen zugeschnittene oder überwachende Ansätze können schaden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=164', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/577', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9199, 22, 16, 'BE', 'Verpflichtende Aus- und Weiterbildung zum Umgang mit extrem rechten Ideologien für Beschäftigte in Bildung, Sozialem, öffentlichem Dienst und Sicherheit.', '{2204}', 8995, 1, 3, null, 'Trainings verbessern Wissen dauerhaft, Einstellungseffekte schwinden aber ohne Einbettung. Erreicht Multiplikatoren, wirkt auf die Bevölkerung nur mittelbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=327', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9200, 22, 16, 'BE', 'Antislawische Feindbilder konsequent thematisieren und ihre Geschichte systematisch aufarbeiten.', '{2204}', 8991, 1, 3, null, 'Setzt an Vorurteilen und Überlegenheitsdenken an; Begegnungsformate wirken eher. Dagegen: Metaanalyse findet bei vielen Vorurteilsprogrammen nur kurzfristige, kleine Effekte und Hinweise auf Publikationsbias.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=273', 'https://collaborate.princeton.edu/en/publications/prejudice-reduction-progress-and-challenges/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9201, 22, 16, 'BE', 'Ressortübergreifende Strategie gegen antimuslimischen Rassismus entwickeln und umsetzen.', '{2204}', 8986, 1, 3, null, 'Kann Prävention bündeln und Lücken schließen; ohne zusätzliche Angebote bleibt die Wirkung aber mittelbar und hängt von der späteren Umsetzung ab. Zur Wirkung solcher Strategien gibt es kaum Studien.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=272', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9202, 22, 16, 'BE', 'Politische Bildung in der Ausbildung und Weiterbildung von Beschäftigten im öffentlichen Dienst stärken.', '{2204}', 8995, 1, 3, null, 'Trainings verbessern Wissen dauerhaft, Einstellungseffekte schwinden aber ohne Einbettung. Erreicht Multiplikatoren, wirkt auf die Bevölkerung nur mittelbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=296', 'https://business.cornell.edu/news/2016/07/28/successful-lasting-diversity-training/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9203, 22, 16, 'BE', 'Öffentliche Kampagnen gegen extrem rechte Ideologien und für Demokratie und Grundrechte.', '{2204}', null, 1, 3, null, 'Aufklärungskampagnen erreichen viele Menschen und setzen an Ideologien an. Dagegen: Wirkung breiter Kampagnen auf Einstellungen meist gering und kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=327', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9204, 22, 16, 'BE', 'Räume für offenen Dialog und Safer Spaces für Menschen mit Migrationsgeschichte und Betroffene von Diskriminierung schaffen.', '{2205}', 9000, 2, 3, null, 'Kontakt verringert Vorurteile laut Metaanalysen und Feldexperimenten. Dagegen: neuere vorregistrierte Studien finden kleinere Effekte, die oft auf die getroffenen Personen begrenzt bleiben.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=269', 'https://forrt.org/open-social-psychology/chapter12.html', 'gemischt', '2026-10-10', false, true, 'blind'),
