  (9250, 22, 17, 'ST', 'Verpflichtende Sprach- und Politikkurse für nicht Deutsch sprechende Zuwanderer', '{2204}', 9006, 1, 1, null, 'Vermittelt demokratische Grundwerte; Integrationskurse regelt aber der Bund, das Land kann kaum verpflichten. Wirkung auf Einstellungen kaum untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=64', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9251, 22, 17, 'ST', 'Ausbau von Friedensbildung, Friedensinitiativen und Städtepartnerschaften', '{2204}', 8990, 1, 3, null, 'Politische Bildung hängt in Studien mit Interesse, Vertrauen und Toleranz zusammen. Dagegen: Effekte auf extremistische Einstellungen klein und kaum kausal belegt; Wirkung hängt stark von Unterrichtsform ab.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=10', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9252, 22, 17, 'ST', 'Projekte, die zu Ausgrenzung, Diffamierung oder Boykott unliebsamer Personen aufrufen, nicht mehr öffentlich fördern', '{2205}', 8989, 1, 3, null, 'Kann bei Teilen der Bevölkerung das Gefühl von Bevormundung und Ungleichbehandlung mindern. Dagegen: Streichungen schwächen Dokumentation und Präventionsarbeit; Wirkung auf Gesprächskultur nicht untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=15', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9253, 22, 17, 'ST', 'Öffentliche Förderung gerecht und nach objektiven Kriterien vergeben; zivilgesellschaftliche Akteure gleich behandeln', '{2205}', 8989, 1, 3, null, 'Kann bei Teilen der Bevölkerung das Gefühl von Bevormundung und Ungleichbehandlung mindern. Dagegen: Streichungen schwächen Dokumentation und Präventionsarbeit; Wirkung auf Gesprächskultur nicht untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=15', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9254, 22, 17, 'ST', 'Förderstrukturen wie „Demokratie leben!“ kritisch überprüfen, wenn sie politische Einseitigkeit verstärken', '{2205}', 8989, 1, 3, null, 'Kann bei Teilen der Bevölkerung das Gefühl von Bevormundung und Ungleichbehandlung mindern. Dagegen: Streichungen schwächen Dokumentation und Präventionsarbeit; Wirkung auf Gesprächskultur nicht untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=14', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9255, 22, 17, 'ST', 'Öffentliche Anhörungen, Beteiligungshaushalte und Bürgerdialoge sollen zur Regel werden', '{2205}', 8998, 1, 3, null, 'Kann Kontrollverlust und Gefühl der Bevormundung mindern. Dagegen: Wirkung hängt davon ab, ob Ergebnisse berücksichtigt werden; ohne Folgen droht Enttäuschung. Kaum untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=11', null, 'offen', '2026-10-10', false, true, 'blind'),
  (9256, 22, 17, 'ST', 'Regelmäßige, repräsentativ besetzte Bürgerräte auf Landes- und Kommunalebene einrichten', '{2205}', 8997, 2, 3, null, 'Deliberation senkte im Feldexperiment affektive Polarisierung deutlich und gibt Mitsprache. Dagegen: erreicht direkt nur wenige; Effekte auf Vertrauen der übrigen Bevölkerung uneinheitlich.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=11', 'https://deliberation.stanford.edu/publications/journal-articles/deliberation-antidote-extreme-partisan-polarization-reflections', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9257, 22, 17, 'ST', 'Entscheidungen aus Volksentscheiden für Regierung und Parlament bindend machen', '{2205}', 8999, 1, 1, null, 'Verfügbare Volksrechte gehen in der Schweiz mit mehr Vertrauen einher, häufige Nutzung teils mit weniger. Quoren stehen meist in der Landesverfassung, Änderung braucht Zweidrittelmehrheit.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=11', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9258, 22, 17, 'ST', 'Beteiligung von Schülerinnen und Schülern an ihren Schulen stärken', '{2205}', 8994, 1, 3, null, 'Mitwirkung in Schulgremien hängt in Panelstudien mit politischer Wirksamkeit und Beteiligung zusammen und übt Streitkultur. Dagegen: Effekt auf Eskalation politischer Gespräche nicht direkt untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=73', 'https://chairedemocratie.openum.ca/fr/publications/the-relation-between-civic-education-and-political-attitudes-and-behavior/', 'gemischt', '2026-10-10', false, true, 'blind'),
  (9259, 22, 17, 'ST', 'Klare Leitlinien und transparente Beschwerdewege an Hochschulen für eine pluralistische Wissenschaftskultur', '{2205}', 9001, 1, 3, null, 'Kann das Gefühl verringern, Positionen würden sanktioniert, und Streit an Hochschulen versachlichen. Dagegen: bestehender Grundrechtsschutz, unklare Reichweite; Wirkung kaum untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=55', null, 'offen', '2026-10-10', false, true, 'blind');

